payload_role_elfldr: "ตัวโหลด ELF โหลดก่อนตัวช่วย PS5Upload",
payload_desc_elfldr: "ตัวโหลดที่รับเพย์โหลด โหลดผ่านการเจลเบรกหรือออโตโหลดเดอร์ก่อนตัวช่วย PS5Upload การส่งต้องมีตัวโหลดที่ทำงานอยู่แล้ว เพราะเปิดพอร์ตที่ปิดอยู่ไม่ได้ เมื่อตัวช่วยเชื่อมต่อแล้ว PS5Upload สามารถแทนที่ตัวโหลดมาตรฐานที่ทำงานอยู่ด้วยรุ่นที่แพตช์ของตัวเอง",
