payload_role_kstuff_lite_drakmor: "ช่องโหว่เคอร์เนล เมานต์อิมเมจเกมได้เร็วกว่า",
payload_desc_kstuff_lite_drakmor: "ฟอร์กของ kstuff-lite ที่เมานต์อิมเมจ .ffpkg และ PFS ได้เร็วกว่า รุ่นใหม่รองรับเฟิร์มแวร์ถึง 12.xx ตรวจสอบบันทึกประจำรุ่นสำหรับเครื่องของคุณ ปิดการเมานต์อัตโนมัติได้ (noautomount) เหมาะที่สุดเมื่อใช้ ShadowMount+ กับอิมเมจเกมเป็นหลัก โหลดก่อน ShadowMount+ และ PS5Upload",
payload_role_shadowmountplus: "เมานต์และลงทะเบียนไฟล์สำรองเกมเอง",
payload_desc_shadowmountplus: "เฝ้าดู /mnt/usb*, /mnt/ext*, /data/homebrew, /mnt/shadowmnt และ /data/shadowmount/manual.lst เพื่อหาโฟลเดอร์เกมและอิมเมจ .ffpkg, .exfat, .ffpfs, .ffpfsc จากนั้นเมานต์ คัดลอกเมทาดาทาและข้อมูลถ้วยรางวัล แล้วเพิ่มลงหน้าจอหลักโดยไม่ต้องสั่ง และยังใช้แบ็กพอร์ต fakelib ด้วย ต้องโหลด kstuff-lite 1.07 ขึ้นไปก่อน",
payload_role_etahen: "ตัวเปิดใช้โฮมบรูและตัวช่วยเจลเบรก",
payload_desc_etahen: "ตัวเปิดใช้โฮมบรูที่ทำงานตลอดพร้อมชุดเครื่องมือ เจลเบรกแอปได้เร็วกว่า และให้บริการคำสั่งบนพอร์ต 9028 ที่แอปโฮมบรูจำนวนมากต้องการ",
payload_role_ftpsrv: "เซิร์ฟเวอร์ FTP",
payload_desc_ftpsrv: "เซิร์ฟเวอร์ FTP ขนาดเล็กบนพอร์ต 2121 ถอดรหัสไฟล์ SELF ขณะอ่าน และเมานต์โฟลเดอร์ใหม่ให้เขียนได้ เรียกดูไฟล์ของ PS5 จากโปรแกรม FTP ใดก็ได้",
payload_role_websrv: "ตัวเปิดโฮมบรูบนหน้าเว็บ",
payload_desc_websrv: "เซิร์ฟเวอร์ HTTP บนพอร์ต 8080 พร้อมหน้าตัวเปิดโฮมบรู ใช้กับชุดโฮมบรูจาก ps5-payload-dev",
payload_role_ps5_app_dumper: "ดัมป์เกมที่ติดตั้งลงไดรฟ์",
payload_desc_ps5_app_dumper: "ดัมป์เกมที่กำลังเล่นแบบถอดรหัสแล้วลงไดรฟ์ USB หรือเครื่อง ทีละเกมหรือเป็นคิว PS5Upload ควบคุมได้ที่ เกม › ดัมป์ (ใส่รหัสที่แสดงบนทีวีหนึ่งครั้ง) และมีหน้าเว็บของตัวเองบนพอร์ต 8081",
payload_role_itemzflow: "ตัวเปิดโฮมบรูบน PS5",
