err_not_enough_space: "คอมพิวเตอร์เครื่องนี้มีที่ว่างไม่พอ: ต้องใช้ {need} และว่าง {free} เพิ่มพื้นที่ว่างแล้วลองอีกครั้ง",
err_link_changed: "ไฟล์ที่ลิงก์นี้เปลี่ยนระหว่างการอ่าน สิ่งที่อ่านแล้วจึงทำต่อให้เสร็จไม่ได้ เริ่มใหม่อีกครั้ง",
err_pair_pending: "PS5 ปฏิเสธการจับคู่ (80108b03) บน PS5 ผู้ใช้ที่คุณเล่นต้องแสดงว่าลงชื่อเข้าใช้แล้ว (การตั้งค่า › ผู้ใช้และบัญชี) และ เปิดใช้งาน Remote Play ต้องเปิดอยู่ (การตั้งค่า › ระบบ › Remote Play) ถ้าอย่างใดอย่างหนึ่งปิดอยู่หรือเป็นสีเทา ให้ทำการลงชื่อเข้าใช้แบบออฟไลน์ใน ตั้งค่าเล่น รีสตาร์ท PS5 แล้วกด จับคู่ อีกครั้ง PS5 ที่สลับไปใช้สภาพแวดล้อม NP sp-int ก็ปฏิเสธเช่นกัน ให้สลับกลับเป็น np ระหว่างจับคู่ ยังถูกปฏิเสธอยู่? กด “จับคู่ด้วย PIN ที่แสดงบน PS5” แล้วพิมพ์ตัวเลขจาก การตั้งค่า › ระบบ › Remote Play › เชื่อมโยงอุปกรณ์",
err_unpack_no_space: "ไดรฟ์นี้มีที่ว่างไม่พอสำหรับอิมเมจที่คลายแล้ว ต้องใช้ขนาดเต็มของอิมเมจบวก 1 GiB",
err_unpack_exists: "ในโฟลเดอร์นี้มีไฟล์ชื่อเดียวกับอิมเมจอยู่แล้ว ย้ายหรือเปลี่ยนชื่อก่อน",
err_unpack_bad: "อ่านไฟล์นี้เป็นอิมเมจเกมที่บีบอัดไม่ได้ หรือไฟล์เสียหาย ไม่ได้เขียนอะไรลงไป",
