err_extract_loader: "ตัวโหลด ELF ของเครื่อง (พอร์ต 9021) ไม่ตอบ ตัวแตกไฟล์จึงเริ่มไม่ได้ โหลด elfldr ใหม่แล้วลองอีกครั้ง",
