localimage_explain: "ระบบจะเปิดอิมเมจเป็นไดรฟ์ธรรมดาบนคอมพิวเตอร์เครื่องนี้ คุณจึงเพิ่ม แทนที่ และลบไฟล์ข้างในได้ — เช่น ไฟล์แพตช์ — ผ่าน Finder หรือ Explorer เหมือนใช้แฟลชไดรฟ์ทุกประการ การเปลี่ยนแปลงจะถูกบันทึกลงในไฟล์อิมเมจโดยตรง ps5upload ไม่เคยเขียนลงอิมเมจเอง แต่ระบบปฏิบัติการของคุณเป็นผู้เขียน เมื่อทำเสร็จแล้วให้นำออกที่นี่",
