"joberr.direct_staged_file_missing": "การอัปโหลดนี้เสร็จสิ้นไปแล้ว จึงไม่มีอะไรเหลือให้เผยแพร่ — และตอนนี้ไฟล์บน PS5 หายไปหรือมีขนาดไม่ถูกต้อง กรุณาอัปโหลดใหม่แล้วเลือก «เขียนทับ» แทน «ทำต่อ»",
"joberr.direct_tx_corrupt": "PS5 ตรวจพบความเสียหายของโปรโตคอลในการถ่ายโอนนี้ กรุณารีสตาร์ท payload จากแท็บ «ส่ง payload» แล้วลองใหม่",
"joberr.direct_writer_io_error": "PS5 มีพื้นที่ว่างไม่พอ (หรือไดรฟ์ภายนอกถูกถอดออก) ขณะเขียนไฟล์ กรุณาเพิ่มพื้นที่ว่างบนไดรฟ์ปลายทางแล้วคลิก «ลองใหม่» — การอัปโหลดจะดำเนินต่อจากจุดที่หยุด",
"joberr.fs_delete_path_not_allowed": "PS5 ปฏิเสธการเข้าถึงพาธนั้น กรุณาใช้ /data/, /user/ หรือพาธที่เมาต์ไว้ใน /mnt/ext* หรือ /mnt/usb*",
"joberr.fs_read_path_not_allowed": "ไฟล์นี้อยู่ในพาร์ทิชันระบบแบบอ่านอย่างเดียวซึ่งปกติถูกบล็อกไว้ กรุณาเปิด การตั้งค่า → «อนุญาตให้ดาวน์โหลดไฟล์ระบบ» เพื่อดาวน์โหลดจาก /system, /system_data และพาธที่ถูกป้องกันอื่น ๆ",
"joberr.fs_write_failed": "PS5 เขียนไปยังปลายทางไม่ได้ระหว่างการถ่ายโอน — ส่วนใหญ่เกิดจากไดรฟ์เต็มหรือไดรฟ์ภายนอกถูกถอดออก กรุณาตรวจสอบพื้นที่ว่างหรือเสียบไดรฟ์ใหม่ แล้วคลิก «ลองใหม่» (การอัปโหลดจะดำเนินต่อจากจุดที่หยุด)",
"joberr.fs_write_failed_no_space": "ไดรฟ์ปลายทางมีพื้นที่ไม่พอ (หรือไฟล์ใหญ่เกินไปสำหรับระบบไฟล์นั้น) กรุณาเพิ่มพื้นที่ว่างบน PS5 หรือไดรฟ์ภายนอก — หรือเลือกปลายทางอื่น — แล้วคลิก «ลองใหม่»",
"joberr.packed_unsupported": "ตัวช่วยของ PS5 ปฏิเสธการถ่ายโอนแบบรวมแพ็ก กรณีนี้เกิดกับ payload รุ่นเก่าเมื่อการอัปโหลดโฟลเดอร์เหลือเพียงไฟล์เล็กไฟล์เดียว (เช่น การทำต่อของเกมที่มีไฟล์เล็กจำนวนมาก) กรุณาอัปเดต ps5upload เป็นเวอร์ชันล่าสุด ส่ง payload ใหม่จากแท็บ «ส่ง payload» แล้วลองอีกครั้ง",
"joberr.preflight_insufficient_space": "ไดรฟ์ปลายทางมีพื้นที่ว่างไม่พอสำหรับไฟล์นี้ กรุณาเพิ่มพื้นที่ว่างบน PS5 (การตั้งค่า → ที่เก็บข้อมูล) หรือเลือกปลายทางอื่น แล้วคลิก «ลองใหม่»",
"joberr.preflight_insufficient_space_image": "โฟลเดอร์นี้อยู่ในอิมเมจเกม และอิมเมจมีที่ว่างไม่พอสำหรับไฟล์นี้ อิมเมจเผื่อที่ว่างไว้เพียงเล็กน้อย การเพิ่มพื้นที่ว่างบน PS5 จึงไม่ช่วย",
"joberr.space_drive": "{volume} ต้องใช้อีก {need} สำหรับการอัปโหลดนี้ แต่ใช้ได้เพียง {avail} (ว่าง {free}, กันไว้ {reserve})",
"joberr.space_image": "การอัปโหลดนี้ต้องใช้อีก {need} แต่อิมเมจมีที่ว่างเพียง {avail} การแทนที่ไฟล์ต้องมีที่สำหรับสำเนาใหม่ขณะที่ไฟล์เก่ายังอยู่ ลบไฟล์เก่าก่อน หรือแก้ไฟล์ในที่ที่สร้างอิมเมจแล้วสร้างใหม่",
