"joberr.space_promised": "กันไว้ {promised} สำหรับการอัปโหลดอื่นที่กำลังทำอยู่",
"joberr.space_reused": "{reused} ของการอัปโหลดนี้อยู่บนเครื่องแล้วและจะนำมาใช้ซ้ำ",
"joberr.size_mismatch": "การถ่ายโอนถูกขัดจังหวะก่อนเสร็จสิ้น — ไฟล์บน PS5 ไม่สมบูรณ์จึงยังไม่ถูกเผยแพร่ (สำเนาเดิมของคุณ ถ้ามี จะไม่ถูกแตะต้อง) โดยทั่วไปหมายความว่า PS5 เข้าสู่โหมดพักหรือไฟดับระหว่างอัปโหลด กรุณาทำให้เครื่องไม่หลับ (การตั้งค่า → ระบบ → การประหยัดพลังงาน → เวลาก่อน PS5 ปิดเครื่อง) แล้วรันรายการนี้ใหม่: «ทำต่อ» จะส่งเฉพาะไฟล์ที่ขาดหายไป ส่วน «เขียนทับ» จะทำสำเนาใหม่ทั้งหมด",
"joberr.ava1_stalled": "การถ่ายโอนไม่คืบหน้าอีกต่อไป (ต้นทางหยุดส่งข้อมูล) ลองอีกครั้ง หากเกิดซ้ำ ให้ตรวจสอบไดรฟ์ต้นทางหรือเน็ตเวิร์กแชร์",
"joberr.ava1_verify_failed": "ไฟล์หนึ่งบนไดรฟ์ของ PS5 ยังคงไม่ตรงกับที่ส่งไป จึงหยุดการโอน ลองอีกครั้ง หากเกิดซ้ำ ไดรฟ์อาจเสีย หรือแอปอื่นบน PS5 อาจกำลังแก้ไขไฟล์นั้น",
"joberr.tx_table_full": "มีการถ่ายโอนพร้อมกันมากเกินไปบน PS5 กรุณารอให้บางรายการเสร็จสิ้น หรือรีสตาร์ท payload",
"joberr.zip_unsupported": "ไฟล์ .zip นี้ใช้สิ่งที่ตัวอัปโหลดสตรีมไม่ได้ (การเข้ารหัส วิธีบีบอัดอื่นที่ไม่ใช่ Deflate, Zstandard หรือ Stored หรือพาธไฟล์ที่ไม่ปลอดภัยหรือซ้ำกัน) โปรดแตกไฟล์บนคอมพิวเตอร์แล้วอัปโหลดโฟลเดอร์แทน",
"joberr.sevenz_unsupported": "ไฟล์ .7z นี้ใช้วิธีบีบอัดหรือฟีเจอร์ที่ตัวอัปโหลดสตรีมไม่ได้ โปรดแตกไฟล์บนคอมพิวเตอร์แล้วอัปโหลดโฟลเดอร์แทน",
"joberr.sevenz_unsupported_layout": "ไฟล์ .7z นี้มีโฟลเดอร์หรือไฟล์ว่างแทรกอยู่ระหว่างไฟล์ภายในบล็อกแบบ solid เดียวกัน ซึ่งเป็นโครงสร้างที่ตัวอัปโหลดสตรีมไม่ได้ โปรดบีบอัดใหม่ด้วย 7-Zip หรือแตกไฟล์แล้วอัปโหลดโฟลเดอร์",
"joberr.rar_unsupported": "ไฟล์ .rar นี้มีพาธไฟล์ที่ซ้ำกันหรือไม่ปลอดภัย หรือฟีเจอร์ที่ตัวอัปโหลดสตรีมไม่ได้ โปรดแตกไฟล์บนคอมพิวเตอร์แล้วอัปโหลดโฟลเดอร์แทน",
"pkg.check_the_ps5": "{label}: ตรวจสอบบน PS5",
"pkg.link_unverified": "PS5 รับลิงก์แล้วและดาวน์โหลดเอง ดูผลได้ที่ดาวน์โหลดบน PS5",
"pkg.all_unconfirmed_body": "ยังไม่ยืนยัน: {n} ตรวจสอบรายการดาวน์โหลดบน PS5 แพ็กเกจเหล่านั้นถูกเก็บไว้",
"pkg.patch_unverified": "PS5 รับอัปเดตนี้แล้ว แต่เวอร์ชันเกมยังไม่เปลี่ยนหลังผ่านไป {minutes} นาที อาจยังติดตั้งอยู่ ให้ตรวจสอบดาวน์โหลดบน PS5 แพ็กเกจยังเก็บไว้ หากเวอร์ชันไม่เปลี่ยนเลย แสดงว่าอัปเดตไม่ตรงกับเกมหลักที่ติดตั้งไว้ ให้ติดตั้งเกมหลักใหม่จากแพ็กเกจของเกมนั้น แล้วลงอัปเดตอีกครั้ง",
"pkg.patch_did_not_apply": "PS5 รับอัปเดตนี้แล้วไม่ได้ทำอะไรกับมันเลย — เกมยังคงเป็นเวอร์ชันเดิม หมายความว่าเครื่องไม่สามารถจับคู่อัปเดตนี้กับเกมหลักที่ติดตั้งไว้ได้ กรุณาติดตั้งเกมหลักใหม่ผ่าน ps5upload จากแพ็กเกจเกมหลักที่มากับอัปเดตนี้ (เลือก «เขียนทับ») แล้วใช้อัปเดตอีกครั้ง",
"pkglib.updateBaseUnknown.title": "อัปเดตนี้อาจไม่ถูกนำไปใช้",
"pkglib.updateBaseUnknown.installAnyway": "ติดตั้งต่อไป",
"pkglib.updateBaseUnknown.body": "{id} ติดตั้งอยู่ แต่ไม่ได้มาจากแพ็กเกจเกมหลักที่ ps5upload ติดตั้ง — PS5 จึงอาจจับคู่อัปเดตนี้กับมันไม่ได้ เมื่อเกิดกรณีนี้ เครื่องจะรายงานว่าสำเร็จแต่ไม่เปลี่ยนอะไรเลย หากหลังจากนั้นเกมยังเป็นเวอร์ชันเดิม ให้ติดตั้งแพ็กเกจเกมหลักที่ตรงกันผ่าน ps5upload (เลือก «เขียนทับ») แล้วใช้อัปเดตนี้อีกครั้ง",
"pkg.patch_regressed": "การติดตั้งอัปเดตนี้ซ้ำกลับทำให้อัปเดตถูกถอดออก — เกมย้อนกลับไปเป็นเวอร์ชันพื้นฐาน ตัวติดตั้งของ PS5 ถือว่าอัปเดตที่ติดตั้งซ้ำคืออัปเดตที่ต้องยกเลิก ให้ติดตั้งอัปเดตอีกครั้งเพื่อกลับไปเป็นเวอร์ชันที่อัปเดตแล้ว และอย่าติดตั้งอัปเดตที่เกมมีอยู่แล้วซ้ำอีก",
