payloads_description_catalog_v2: "เพย์โหลดโฮมบรู PS5 จากบุคคลที่สามที่คัดสรรแล้ว ตรวจหารุ่นล่าสุด ดาวน์โหลดครั้งเดียว แล้วส่งไปยัง PS5 ในคลิกเดียว เวอร์ชันต่างๆ ถูกแคชในเครื่อง คุณจึงนำไปใส่ USB เพย์โหลดได้ด้วย",
payloads_description_send_v2: "ส่งไฟล์เพย์โหลด PS5 ใดก็ได้ — .elf, .bin, .js, .lua หรือ .jar (kstuff, ตัวโหลดโฮมบรูแบบกำหนดเอง, ช่องโหว่ขั้นเบราว์เซอร์, สคริปต์ปลั๊กอิน, BD-JB JAR) — ไปยัง PS5 ขั้นตอนเหมือนหน้าการเชื่อมต่อ แค่ชี้ไปที่ไฟล์ที่คุณเลือก พอร์ตเป็นไปตามชนิดไฟล์ (.elf/.bin 9021, .jar 9025, .lua 9026, .js 50000) เปลี่ยนเฉพาะเมื่อตัวโหลดของคุณรอรับที่พอร์ตอื่น",
