ps5notif_empty_hint_v2: "เมื่อ ps5upload แสดงข้อความบนทีวีของคุณ เช่น PIN ของ Remote Play หรือการเปิดสูตรโกง ข้อความจะแสดงที่นี่ให้คุณอ่านซ้ำได้ นี่ไม่ใช่แผงการแจ้งเตือนของ PS5 เอง เครื่องไม่อนุญาตให้เราอ่านแผงนั้น",
reset_confirm_body_browser: "การดำเนินการนี้ล้างการตั้งค่าและสถานะที่บันทึกไว้ทั้งหมดที่เบราว์เซอร์นี้เก็บไว้สำหรับ PS5Upload และหน้าจะโหลดใหม่ทั้งหมด ข้อมูลของเอนจินบนเซิร์ฟเวอร์ (การจับคู่เครื่อง, คอลเลกชัน, เซิร์ฟเวอร์ที่บันทึก, ไลบรารีแบ็กพอร์ต, ประวัติการติดตั้ง, บันทึก) จะไม่ถูกแตะต้อง และไม่มีสิ่งใดบน PS5 ถูกแตะต้อง ไม่สามารถย้อนกลับได้",
reset_confirm_body_v2: "การดำเนินการนี้ลบข้อมูล PS5Upload ในเครื่องทั้งหมดอย่างถาวร: การตั้งค่า, PS5 ที่บันทึกไว้และการจับคู่, คอลเลกชัน, เซิร์ฟเวอร์ที่บันทึกและรหัสผ่าน, ไลบรารีแบ็กพอร์ต, ประวัติการติดตั้ง, งานและเหตุการณ์, ประวัติกิจกรรม/คิว, บันทึก, แคชเพย์โหลด และรายงานข้อขัดข้อง จะไม่แตะต้องสิ่งใดบน PS5 ของคุณ แอปจะโหลดใหม่เป็นสถานะเริ่มต้น ไม่สามารถย้อนกลับได้",
reset_hint_browser: "ล้างการตั้งค่าและสถานะที่บันทึกไว้ทั้งหมดที่เบราว์เซอร์นี้เก็บไว้สำหรับ PS5Upload แล้วเริ่มใหม่ สิ่งที่เอนจินเก็บไว้บนเซิร์ฟเวอร์ (การจับคู่เครื่อง, คอลเลกชัน, เซิร์ฟเวอร์ที่บันทึก, ไลบรารีแบ็กพอร์ต, ประวัติการติดตั้ง, บันทึก) จะไม่ถูกแตะต้อง และไม่มีสิ่งใดบน PS5 ได้รับผลกระทบ",
reset_hint_v2: "ลบร่องรอยทั้งหมดของ PS5Upload ในเครื่องแล้วเริ่มใหม่: การตั้งค่า, PS5 ที่บันทึกไว้และการจับคู่, คอลเลกชัน, เซิร์ฟเวอร์ที่บันทึกและรหัสผ่าน, ไลบรารีแบ็กพอร์ต, ประวัติการติดตั้ง, งานและเหตุการณ์, ประวัติกิจกรรม/คิว, บันทึก, แคชเพย์โหลด และรายงานข้อขัดข้อง ไม่มีสิ่งใดบน PS5 ได้รับผลกระทบ สำรอง / กู้คืน ด้านบนไม่ครอบคลุมการจับคู่ คอลเลกชัน รหัสผ่านเซิร์ฟเวอร์ หรือไลบรารีแบ็กพอร์ต",
saves_backup_usb_tooltip_v2: "บีบอัดเซฟนี้เป็น zip ลงไดรฟ์ที่พาธเซฟที่ตั้งไว้ในการตั้งค่า (ไดรฟ์ USB บน PS5) เซฟจะถูกคัดลอกมายังคอมพิวเตอร์นี้ บีบอัด แล้วส่งกลับ จึงควรเปิดแอปไว้ สำเนาที่นี่จะถูกลบหลังจากนั้น",
saves_description_browser: "ข้อมูลเซฟบน PS5 หนึ่งรายการต่อเกม การสำรองเซฟเป็น .zip และการกู้คืนต้องใช้แอปเดสก์ท็อป ที่นี่คุณดูและเปิดโฟลเดอร์ของเซฟได้",
saves_restore_usb_tooltip_v2: "กู้คืนเซฟนี้จากไฟล์สำรองล่าสุดที่พาธเซฟที่ตั้งไว้ในการตั้งค่า ไฟล์ zip จะถูกคัดลอกมายังคอมพิวเตอร์นี้ แตกไฟล์ แล้วส่งกลับไปยัง PS5 จึงควรเปิดแอปไว้ จะเขียนทับเซฟปัจจุบัน",
