"profile.np.no_backup": "บัญชีนี้มีการตั้งค่าแม่แบบของ np-fake-signin (วันเกิด 1983-04-12, ปิดแฟล็กผู้ใหญ่แบบออฟไลน์) และไม่มีสำเนาจากก่อนหน้านี้บน PS5 เครื่องนี้ แอปจึงยกเลิกไม่ได้ หาก PS5 ขอให้ปิดการจำกัดคอนโซลชั่วคราวก่อนเปิดเกม: การตั้งค่า > ครอบครัวและการควบคุมโดยผู้ปกครอง > การจำกัดคอนโซล PS5 (รหัสผ่าน 0000 หากยังไม่ได้เปลี่ยน) แล้วยกเลิกการจำกัดที่นั่น",
