"fpkg.image.zstd": "แพ็กแอสเซ็ต zstd (เล็กที่สุด สำหรับ ShadowMount+)",
"fpkg.image.zstd_body": "แพ็กทุกอย่างยกเว้นไฟล์ระบบของเกมลงในแพ็ก zstd เขียนลงอิมเมจโดยตรงโดยไม่มีสำเนาชั่วคราว อิมเมจจะได้ ampr-emu-ng ของ quer3q เป็นอีมูเลเตอร์ ซึ่งตรวจสอบกับไดเจสต์ที่เผยแพร่ก่อนใช้งาน เกมที่อยู่ในแพ็ก LZ4 แล้วจะถูกเปลี่ยน ปิด update_emulators ใน ShadowMount+ ไม่เช่นนั้นอาจสลับอีมูเลเตอร์เป็นตัวที่อ่านแพ็กเหล่านี้ไม่ได้",
"fpkg.image.zstd_level": "ระดับการบีบอัด",
"fpkg.image.zstd_runtime": "รันไทม์ของแพ็ก",
"fpkg.image.zstd_runtime_latest": "รุ่นล่าสุด (ค่าเริ่มต้น)",
"fpkg.image.zstd_runtime_pinned": "รุ่นที่ทดสอบแล้ว {version}",
"fpkg.image.zstd_runtime_body": "“ล่าสุด” ใช้ ampr-emu-ng รุ่นใหม่สุดบน GitHub เฉพาะเมื่อตรงกับ SHA-256 ที่ GitHub เผยแพร่ไว้ ไม่เช่นนั้นหรือเมื่อออฟไลน์ จะใช้รุ่นที่ทดสอบแล้ว {version} ส่วน “ทดสอบแล้ว” ใช้ {version} เสมอ",
"fpkg.folder.zstd_body": "เขียนเกมเป็นโฟลเดอร์ธรรมดา ทุกอย่างยกเว้นไฟล์ระบบอยู่ในแพ็ก zstd และมี ampr-emu-ng ของ quer3q เป็น fakelib/libSceAmpr.sprx ต้นทางเป็นโฟลเดอร์เกมก็ได้ ที่นี่ไม่มีแพ็ก LZ4 ให้เลือก เพราะใช้ได้กับอิมเมจ .exfat เท่านั้น ปิด update_emulators ใน ShadowMount+ ไม่เช่นนั้นอาจสลับอีมูเลเตอร์เป็นตัวที่อ่านแพ็กเหล่านี้ไม่ได้",
"ampr_emu_add_hint": "เกมนี้อ่านไฟล์ผ่าน AMPR และไม่มีอีมูเลเตอร์ เกมแบบนี้บางเกมเริ่มจากอิมเมจไม่ได้หากไม่มี บางเกมก็เล่นได้ปกติ จะเพิ่ม ampr_emu 0.4.2.1 ของ drakmor โดยดาวน์โหลดครั้งเดียวและตรวจกับค่าแฮชที่ทราบ อิมเมจไม่เปลี่ยนแปลง อีมูเลเตอร์จะอยู่ในโฟลเดอร์ backport ของ ShadowMount+",
"ampr_emu_done_backport": "เพิ่มเป็น backport ของ ShadowMount+ ใน {folder} แล้ว อิมเมจไม่เปลี่ยนแปลง เริ่มเกมเพื่อลอง",
"ampr_emu_done_folder": "เพิ่มลงในโฟลเดอร์เกม {folder} แล้ว เริ่มเกมเพื่อลอง",
"fpkg.fake_sign_note": "ไฟล์ปฏิบัติการธรรมดา (ไม่ได้ลงนาม) {count} ไฟล์ของเกมนี้จะถูกลงนามปลอมระหว่างแปลง ไม่เช่นนั้นเกมจะไม่เริ่ม ต้นฉบับไม่เปลี่ยนแปลง",
"fpkg.image.ampr_emu": "เพิ่มอีมูเลเตอร์ AMPR",
"fpkg.image.ampr_emu_body": "เกมนี้อ่านไฟล์ผ่าน AMPR และไม่มีอีมูเลเตอร์ เกมแบบนี้บางเกมเริ่มจากอิมเมจไม่ได้หากไม่มี บางเกมก็เล่นได้ปกติ จะเพิ่ม ampr_emu 0.4.2.1 ของ drakmor เป็น fakelib/libSceAmpr.sprx โดยดาวน์โหลดครั้งเดียวจากรุ่นบน GitHub และตรวจกับค่าแฮชที่ทราบ",
"fpkg.image.lz4_placement_note": "เก็บอิมเมจที่แพ็กไว้ในที่เก็บข้อมูลภายในของเครื่อง: มีรายงานว่าเมื่อรันจาก USB ค้างที่หน้าจอดำ ปิด update_emulators ใน ShadowMount+ ไม่เช่นนั้นอาจเปลี่ยนอีมูเลเตอร์เป็นตัวที่อ่านแพ็กไม่ได้",
