mcp_update_address: "หากที่อยู่ของเอนจินเปลี่ยน แอปจะแจ้งเมื่อเริ่มทำงาน และการ์ดของเอเจนต์ที่นี่จะแสดงปุ่มอัปเดต คลิกครั้งเดียวก็แก้ได้",
mcp_update_by_hand: "แอปมองไม่เห็น Gemini CLI, Cursor, Claude Desktop หรือสคริปต์ของคุณ หากที่อยู่ตรงนี้เปลี่ยน หรือมีตัวใดเชื่อมต่อไม่ได้หลังอัปเดต ให้คัดลอกการตั้งค่าอีกครั้งจากเอเจนต์และแอปอื่นๆ",
