"pairing_closed_body_v4": "PS5 เครื่องนี้ถามก่อนให้อุปกรณ์ใหม่เชื่อมต่อ และตอนนี้แสดงว่าอุปกรณ์นี้กำลังขอเข้า บนอุปกรณ์ที่ใช้ PS5 เครื่องนี้อยู่แล้ว (การเชื่อมต่อ) หรือบนหน้าของ PS5 เอง (การตั้งค่า › อุปกรณ์) กดอนุญาต แล้วแอปนี้จะเข้าได้เอง หรือกดส่งตัวช่วยอีกครั้ง ซึ่งจะให้แอปนี้เข้าได้",
