"cw_tn_sign_out_confirm": "ออกจากระบบ Tailscale บน PS5 เครื่องนี้ไหม? การลงชื่อเข้าใช้จะถูกลืม ต้องลงชื่อเข้าใช้ใหม่ และอาจได้ที่อยู่ใหม่ หากจะหยุดสักพัก ให้ปิดแทน",
