"cw_tn_allow_all": "ทุกอุปกรณ์ในเครือข่าย Tailscale ของคุณเข้าถึง PS5 เครื่องนี้ได้ เปลี่ยนได้ในแอป PS5Upload: การเชื่อมต่อ › Tailscale สำหรับ PS5 เครื่องนี้",
