"cw_tn_allow_none": "เฉพาะอุปกรณ์ที่คุณเพิ่มเท่านั้นที่เข้าถึง PS5 เครื่องนี้ผ่าน Tailscale ได้ เปิด PS5Upload ที่บ้านบนแต่ละเครื่องหนึ่งครั้ง หรือติ๊กอุปกรณ์ในแอป (การเชื่อมต่อ › Tailscale สำหรับ PS5 เครื่องนี้)",
