"settings_ps5_none_title": "ยังไม่มี PS5",
"settings_ps5_none_body": "เพิ่ม PS5 ของคุณที่หน้าการเชื่อมต่อ แล้วการตั้งค่าของเครื่องจะอยู่ที่นี่",
"settings_ps5_open_connection": "เปิดการเชื่อมต่อ",
"settings_ps5_picker": "PS5",
"settings_ps5_picker_hint": "การตั้งค่าเหล่านี้เป็นของ PS5 เครื่องนี้เท่านั้น คอนโซลแต่ละเครื่องมีของตัวเอง และติดตามไปยังอุปกรณ์อื่นของคุณด้วย",
"auto_bringup_hint_ps5": "เมื่อตัวโหลดของ PS5 เครื่องนี้ (elfldr, พอร์ต 9021) ทำงานอยู่และตัวช่วยไม่ได้ทำงาน แอปจะเริ่มระบบอย่างรวดเร็วเอง: เพลย์ลิสต์เริ่มระบบของ PS5 เครื่องนี้ถ้าตั้งไว้ จากนั้นตัวช่วย แล้วเพลย์ลิสต์ตัวโหลดอัตโนมัติของคุณ ทำครั้งเดียวทุกครั้งที่ PS5 เครื่องนี้เปิด หลังโหมดพักจะส่งเฉพาะตัวช่วยอีกครั้ง แอปจะรอประมาณ 90 วินาทีหลังตัวโหลดปรากฏ เพื่อให้ตัวโหลดอัตโนมัติของคอนโซลทำงานเสร็จก่อน ปิดไว้เป็นค่าเริ่มต้น",
"bringup_playlist_label_ps5": "เพลย์ลิสต์เริ่มระบบสำหรับ PS5 เครื่องนี้ (kernel R/W, SMP)",
"bringup_playlist_hint_ps5": "ทำงานก่อนตัวช่วยระหว่างเริ่มระบบอย่างรวดเร็ว เพย์โหลดขึ้นกับเฟิร์มแวร์ PS5 แต่ละเครื่องจึงมีเพลย์ลิสต์ของตัวเอง สร้างเพลย์ลิสต์ได้ในเพย์โหลด",
"upload_auto_redeploy_on_wake_hint_ps5": "เมื่อตัวช่วยของ PS5 เครื่องนี้ออฟไลน์ (โหมดพัก เปลี่ยน Wi-Fi หรือเพย์โหลดขัดข้อง) ให้พยายามส่งใหม่ในเบื้องหลังต่อไป เพื่อให้ตัวช่วย ค่าเกณฑ์พัดลมของ PS5 เครื่องนี้ และพอร์ตอัปโหลดกลับมาเองเมื่อเข้าถึงได้อีกครั้ง เปิดไว้เป็นค่าเริ่มต้น",
"keep_ps5_awake_mode_hint_ps5": "รีเซ็ตตัวจับเวลาสแตนด์บายอัตโนมัติของ PS5 เครื่องนี้เพื่อไม่ให้เข้าโหมดพัก “ระหว่างอัปโหลดและติดตั้ง” ปกป้องการอัปโหลดที่ใช้เวลานาน (สาเหตุที่พบบ่อยของการอัปโหลดล้มเหลว ค่าเริ่มต้น) “ตลอดเวลาที่เชื่อมต่อ” กัน PS5 เครื่องนี้ไม่ให้เข้าโหมดพักขณะที่ตัวช่วยทำงานและแอปเปิดอยู่ การสั่งให้ PS5 เข้าโหมดพักเองยังใช้ได้ในทุกโหมด",
"upload_rest_after_hint_ps5": "เมื่อคิวอัปโหลดของ PS5 เครื่องนี้เสร็จ ให้สั่งเข้าโหมดพัก สะดวกสำหรับคิวข้ามคืน เฉพาะเมื่อมีการอัปโหลดสำเร็จอย่างน้อยหนึ่งรายการ (ไม่ใช่หลังกดหยุดหรือเมื่อล้มเหลวทั้งหมด) ปิดไว้เป็นค่าเริ่มต้น เฟิร์มแวร์บางรุ่นปฏิเสธโหมดพัก คุณจะได้รับแจ้งถ้า PS5 เครื่องนี้ปฏิเสธ",
"upload_wake_for_uploads_hint_ps5": "เมื่อมีการอัปโหลดรอ PS5 เครื่องนี้ที่อยู่ในโหมดพัก ให้ส่งสัญญาณปลุกและทำต่อเมื่อตัวช่วยกลับมา ต้องตั้งค่าการปลุกสำหรับ PS5 เครื่องนี้ที่หน้าการเชื่อมต่อ เปิดไว้เป็นค่าเริ่มต้น",
"install_path_fallback_hint_ps5": "ทางเลือกสุดท้ายสำหรับแพ็กเกจที่อยู่บน PS5 เครื่องนี้แล้ว เมื่อเครื่องปฏิเสธแพ็กเกจจากที่เก็บข้อมูลของตัวเองและดึงจากคอมพิวเตอร์นี้ไม่ได้ด้วย ใช้เฉพาะกับเกมหลักที่ยังไม่ได้ติดตั้ง จึงลบอะไรไม่ได้ ยังไม่ได้พิสูจน์: เคยใช้ได้บนเฟิร์มแวร์ 11.20 และถูกปฏิเสธบน 13.60 จึงตั้งแยกสำหรับ PS5 แต่ละเครื่อง ถ้าลองแล้ว ช่วยแจ้งว่าได้ผลหรือไม่",
